const pages=$input.all().map((x,i)=>{const p=$('Number every source page').itemMatching(i).json.page;
if(typeof x.json.markdown!=='string') throw new Error('Expected inline markdown for page '+p);
return {page:p,text:x.json.markdown};}).sort((a,b)=>a.page-b.page);
